module JC_counter(
    input clk, 
    input rst_n,
    output reg [63:0] Q
);
// Sequential logic block triggered on the positive edge of the clock signal (posedge clk) or the negative edge of the reset signal (negedge rst_n)
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        // If the reset signal is active (rst_n == 0), the counter value (Q) is initialized to 0
        Q <= 64'b0;
    end else begin
        // Otherwise, based on the least significant bit (Q[0]), the counter either increments or decrements its value by shifting the bits to the right and appending a 1 or 0 at the most significant bit position
        if (Q[0] == 1'b0) begin
            Q <= {1'b1, Q[63:1]};
        end else begin
            Q <= {1'b0, Q[63:1]};
        end
    end
end
endmodule
